set -euo pipefail

if [ "$#" -ne 6 ]; then
  echo "usage: $0 <mashmap> <reference.fa> <query.fa> <threads> <identity-percent> <output>" >&2
  exit 1
fi

mashmap="$1"
reference="$2"
query="$3"
threads="$4"
identity="$5"
output="$6"

# MashMap requires an output filename.  Feeding it a named pipe is portable
# across macOS and Linux, unlike /dev/fd process-substitution paths.  The awk
# reader filters records concurrently, so the potentially enormous unfiltered
# all-vs-all mapping is never stored on disk.
output_dir=$(dirname "$output")
output_name=$(basename "$output")
fifo="${output_dir}/.${output_name}.pipe.$$"
working="${output}.WORKING"
filter_pid=""

cleanup() {
  status=$?
  trap - EXIT INT TERM HUP
  if [ -n "$filter_pid" ]; then
    kill "$filter_pid" 2>/dev/null || true
    wait "$filter_pid" 2>/dev/null || true
  fi
  rm -f "$fifo" "$working"
  exit "$status"
}
trap cleanup EXIT INT TERM HUP

rm -f "$fifo" "$working"
mkfifo "$fifo"
awk '$11 >= 50000' < "$fifo" > "$working" &
filter_pid=$!

"$mashmap" \
  -r "$reference" \
  -q "$query" \
  -t "$threads" \
  -f none \
  --pi "$identity" \
  -s 10000 \
  -o "$fifo"

# Do not publish a partial Snakemake output: wait for awk, then atomically move
# its completed temporary file into place.
wait "$filter_pid"
filter_pid=""
mv "$working" "$output"
rm -f "$fifo"
trap - EXIT INT TERM HUP
